import bisect

def preview(n, a, b, t, S):
	t -= b + 1 if S[0] else 1
	S[0] = False
	if t < 0:
		return 0
	R = []
	s = 0
	for i in range(1, n):
		s += a + (b + 1 if S[i] else 1)
		if s > t:
			break
		R.append(s)
	else:
		return n
	L = []
	s = 0
	for i in reversed(range(1, n)):
		s += a + (b + 1 if S[i] else 1)
		if s > t:
			break
		L.append(s)
	m = 1 + max(len(R), len(L))
	ai = 0
	j = len(L) - 1
	for i in range(len(R)):
		ai += a
		t1 = t - R[i] - ai
		if t1 < 0:
			break
		j = bisect.bisect_right(L, t1, hi=j + 1) - 1
		if j < 0:
			break
		m = max(m, i + j + 3)
	ai = 0
	j = len(R) - 1
	for i in range(len(L)):
		ai += a
		t1 = t - L[i] - ai
		if t1 < 0:
			break
		j = bisect.bisect_right(R, t1, hi=j + 1) - 1
		if j < 0:
			break
		m = max(m, i + j + 3)
	assert m < n
	return m

def main():
