import sys

def readint():
	return int(input())

def readinti():
	return map(int, input().split())

def readintl():
	return list(readinti())

def readintt():
	return tuple(readinti())

def readintll(k):
	return [readintl() for _ in range(k)]

def readinttl(k):
	return [readintt() for _ in range(k)]

